    registerFacadeTool(
      "easyeda_control_runtime",
      {
        title: "Manage the retained EasyEDA execution runtime",
        description: "Inspect or launch the retained EasyEDA runtime, request normal close, or open an exact existing project/document from Start Page with checkpoint/registry membership, exclusive-tab guards, tracked recovery and complete unchanged-database proof. Opening never replaces another project, saves or discards. Does not attach to an unowned instance or force-terminate it.",
        inputSchema: { request: runtimeRequestSchema },
        annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false }
      },
      serializedGuarded(async ({ request }) => {
        if (request.action === "status") {
          return { action: request.action, result: windowsRuntime?.status() ?? { state: "not-launched" } };
        }
        if (request.action === "launch-contained") {
          const assetsRoot = process16.env["EASYEDA_ASSETS_ROOT"];
          if (assetsRoot === void 0) {
            throw new Error("Configure the machine's installed EasyEDA assets first.");
          }
          const implementation = await engine.controlFingerprintPromise;
          windowsRuntime ??= new WindowsControlRuntime({
            upstream,
            pluginRoot: resolve10(import.meta.dirname, "../.."),
            assetsRoot,
            reviewedExecutionScopeSha256: implementation.sha256
          });
          return { action: request.action, result: await windowsRuntime.launch() };
        }
        if (request.action === "normal-close") {
          await ownedWindowsRuntime().normalClose(request.windowHandle);
          return { action: request.action, result: ownedWindowsRuntime().status() };
        }
        if (request.action === "inspect-open") {
          return { action: request.action, result: await projectOpenExecutor.inspect(request.operationId) };
        }
        if (request.action !== "recover-open-authority") {
          await engine.assertBridgeDispatchAllowed();
        }
        return upstream.withAuthenticatedBridgeDispatchScope(async () => {
          switch (request.action) {
            case "open-existing": {
              return { action: request.action, result: await projectOpenExecutor.openExisting(request) };
            }
            case "recover-open-authority": {
              return { action: request.action, result: await projectOpenExecutor.recoverAuthority(request.operationId) };
            }
            case "reconcile-open": {
              return { action: request.action, result: await projectOpenExecutor.reconcileNoMutation(request.operationId) };
            }
            case "inspect-editor-tabs": {
              return { action: request.action, result: await projectOpenExecutor.inspectEditorTabs(request.operationId) };
            }
            case "rebind-open-runtime": {
              return { action: request.action, result: await projectOpenExecutor.rebindRuntime(request.operationId, request.expectedFingerprint) };
            }
            default: {
              throw new Error("Unknown project-open runtime request.");
            }
          }
        });
      }, { allowDuringOrphanRisk: true })
    );
